<template>
  <main class="privacy-detail-page">
    <div class="container">
      <nav class="policy-nav">
        <router-link to="/privacy">← {{ copy.back }}</router-link>
        <button type="button" @click="toggleLanguage">{{ language === 'en' ? 'Español' : 'English' }}</button>
      </nav>
      <article class="privacy-content glass-card">
        <p class="policy-brand">FATCAT GAME STUDIO · {{ game.name }}</p>
        <h1>{{ copy.title }}</h1>
        <p class="intro">{{ policyCopy ? policyCopy.intro : copy.intro }}</p>
        <p class="updated">{{ copy.updated }}: {{ updatedDate }}</p>

        <template v-if="policyCopy">
          <section v-for="section in policyCopy.sections" :key="section.title">
            <h2>{{ section.title }}</h2><p>{{ section.body }}</p>
          </section>
          <section>
            <h2>{{ policyCopy.providerTitle }}</h2><p>{{ policyCopy.providerLead }}</p>
            <ul><li v-for="service in game.services" :key="service.name"><a :href="service.url" target="_blank" rel="noopener noreferrer">{{ service.name }}</a></li></ul>
          </section>
        </template>
        <template v-else>
          <section><h2>{{ copy.directTitle }}</h2><p>{{ copy.direct }}</p></section>
          <section><h2>{{ copy.technicalTitle }}</h2><p>{{ copy.technical }}</p></section>
          <section v-if="game.services.some(service => service.name.includes('LevelPlay') || service.name.includes('Gley'))"><h2>{{ copy.adsTitle }}</h2><p>{{ copy.ads }}</p></section>
          <section v-if="game.services.some(service => service.name.includes('RevenueCat'))"><h2>{{ copy.purchaseTitle }}</h2><p>{{ copy.purchases }}</p></section>
          <section><h2>{{ copy.childrenTitle }}</h2><p>{{ copy.children }}</p></section>
          <section><h2>{{ copy.sharingTitle }}</h2><p>{{ copy.sharing }}</p><ul><li v-for="service in game.services" :key="service.name"><a :href="service.url" target="_blank" rel="noopener noreferrer">{{ service.name }}</a></li></ul></section>
          <section><h2>{{ copy.retentionTitle }}</h2><p>{{ copy.retention }}</p></section>
          <section><h2>{{ copy.securityTitle }}</h2><p>{{ copy.security }}</p></section>
          <section><h2>{{ copy.changesTitle }}</h2><p>{{ copy.changes }}</p></section>
        </template>
        <section class="contact"><h2>{{ copy.contactTitle }}</h2><p>{{ copy.contact }} <a :href="`mailto:${common.email}`">{{ common.email }}</a>.</p></section>
      </article>
    </div>
  </main>
</template>

<script>
import { common, gamePolicies } from '@/data/gamePrivacy';
import { getInitialSiteLanguage } from '@/i18n/language';

export default {
  name: 'PrivacyPolicy',
  props: { gameId: { type: String, required: true } },
  data() { return { common, language: getInitialSiteLanguage() }; },
  computed: {
    game() { return gamePolicies[this.gameId] || gamePolicies.mix2word; },
    policyCopy() { return this.game.policy && this.game.policy[this.language]; },
    copy() { return common.languages[this.language]; },
    updatedDate() { return new Intl.DateTimeFormat(this.language === 'es' ? 'es-PE' : 'en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' }).format(new Date(`${this.game.updated || common.updated}T00:00:00Z`)); },
  },
  methods: {
    toggleLanguage() {
      this.language = this.language === 'en' ? 'es' : 'en';
      document.documentElement.lang = this.language;
    },
  },
  mounted() { document.documentElement.lang = this.language; },
};
</script>

<style lang="scss" scoped>
@use "@/styles/design-system.scss" as *;
.privacy-detail-page { min-height: 100vh; padding: $space-8 $space-4; }
.container { max-width: $container-md; margin: 0 auto; }
.policy-nav { display: flex; align-items: center; justify-content: space-between; margin-bottom: $space-5; }
.policy-nav a, .policy-nav button { color: $accent-cyan; font: inherit; font-weight: $font-semibold; text-decoration: none; }
.policy-nav button { border: 1px solid $glass-border; border-radius: $radius-full; padding: $space-2 $space-4; background: transparent; cursor: pointer; }
.privacy-content { padding: $space-10 $space-8; @media (max-width: $breakpoint-md) { padding: $space-6 $space-4; } }
.policy-brand { color: $accent-cyan !important; text-align: center; font-size: $text-sm; letter-spacing: .12em; font-weight: $font-bold; }
h1 { margin: $space-2 0; text-align: center; font-size: $text-4xl; }
.intro { text-align: center; font-size: $text-lg; }
.updated { text-align: center; color: $text-secondary; font-size: $text-sm; }
section { margin-top: $space-6; h2 { color: $accent-cyan; font-size: $text-xl; margin-bottom: $space-3; } }
p, li { color: $text-secondary; line-height: $leading-relaxed; }
li { margin: $space-2 0; }
